/**
 * Id of the notification this event was fired for.
 *
 * @type {string}
 */
notificationId;

/**
 *
 * @param {string} type - Event type.
 * @param {MouseEvent} event - Mouse event this is inheriting from.
 * @param {string} notificationId - ID of the notification this event is
 *   emitted for.
 */
constructor(type, event, notificationId) {
  super(type, event);
  this.notificationId = notificationId;
}

const notificationEvent = new InAppNotificationEvent("test", mouseEvent, 7);
Assert.equal(notificationEvent.type, "test", "Should have custom type");
Assert.strictEqual(
  notificationEvent.button,
  0,
  "Should inherit button from mouse event"

Assert.equal(
  notificationEvent.notificationId,
  7,
  "Should have extra notificationId property"
);
